import{_ as a,o as l,a as d,b as r}from"./app.BGziXukh.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMT API","link":"/api/SIMT-API/SIMT-API"},{"text":"数学函数","link":"/api/SIMT-API/math_functions/math_functions"},{"text":"通用约束说明","link":"/api/SIMT-API/math_functions/common_constraints"}]},"headers":[],"relativePath":"api/SIMT-API/math_functions/common_constraints.md","filePath":"api/SIMT-API/math_functions/common_constraints.md","outlineHeaders":[{"level":2,"title":"饱和模式设置","slug":"饱和模式设置","link":"#饱和模式设置"},{"level":3,"title":"饱和行为","slug":"饱和行为","link":"#饱和行为"},{"level":3,"title":"控制饱和行为的方式","slug":"控制饱和行为的方式","link":"#控制饱和行为的方式"}],"lastUpdated":1794984466000}'),i={name:"api/SIMT-API/math_functions/common_constraints.md"};function e(n,t,o,s,h,_){return l(),d("div",null,[...t[0]||(t[0]=[r('<div><article class="markdown-body"><h1>通用约束说明</h1><p>本文介绍SIMT数学函数与类型转换接口的通用约束。当前内容包括饱和模式设置：饱和行为对nan、inf特殊值以及转换后超出目标类型范围结果的处理方式，以及CTRL寄存器与接口后缀对饱和行为的控制方式。饱和与溢出的系统性介绍请参见《浮点计算基础》的<a href="../../../guide/technical_appendix/floating_point_computation/floating_point_basics.html#%E9%A5%B1%E5%92%8C%E4%B8%8E%E6%BA%A2%E5%87%BA%E5%A4%84%E7%90%86">饱和与溢出处理</a>章节。</p><h2 id="饱和模式设置">饱和模式设置<a class="header-anchor" href="#饱和模式设置">​</a></h2><h3 id="饱和行为">饱和行为<a class="header-anchor" href="#饱和行为">​</a></h3><p><strong>表1</strong> 饱和行为的模式说明</p><table><thead><tr><th>模式</th><th>描述</th><th>接口名格式</th></tr></thead><tbody><tr><td>非饱和模式</td><td>默认模式。<br>如果输入超出该类型所能表示的范围，转换结果为对应符号的inf值。<br>如果输入为nan，转换结果为nan。</td><td>srctype2dsttype_r[xx]</td></tr><tr><td>饱和模式</td><td>饱和模式下：<br>如果输入为+inf，或者超出该类型所能表示的最大值，转换结果为最大值。<br>如果输入为-inf，或者小于该类型所能表示的最小值，转换结果为最小值。<br>如果输入为nan，转换结果为0。</td><td>srctype2dsttype_r[xx]_sat</td></tr></tbody></table><h3 id="控制饱和行为的方式">控制饱和行为的方式<a class="header-anchor" href="#控制饱和行为的方式">​</a></h3><p>饱和行为受寄存器CTRL[60]、CTRL[48]和接口功能同时控制，SIMD与SIMT混合编程场景下，CTRL寄存器的设置请参考<a href="../../SIMD-API/basic_api/special_register_access/SetCtrlSpr_ISASI.html">SetCtrlSpr(ISASI)</a>接口。<strong>SIMT编程场景暂不支持设置CTRL寄存器。</strong></p><p>宽范围数据转成窄范围数据且转换的目标类型不是float时，包括float转half、float转bfloat16_t、bfloat16_t转half、float或half转hifloat8_t、fp8_e4m3fn_t或fp8_e5m2_t，接口的饱和行为受硬件寄存器CTRL[60]和CTRL[48]的影响。具体行为如下：</p><ul><li><p>当CTRL[60] = 0时，饱和行为受接口独立控制。</p><ul><li>后缀__sat的接口转换结果为饱和模式。</li><li>不带__sat后缀的接口转换结果为非饱和模式。</li></ul></li><li><p>当CTRL[60] = 1时，饱和行为只受CTRL[48]全局控制。</p><ul><li>当CTRL[48] = 1时，接口转换结果为非饱和模式。</li><li>当CTRL[48] = 0时，接口转换结果为饱和模式。</li></ul></li></ul><p><strong>表2</strong> 宽范围数据转窄范围数据的最终饱和行为</p><table><thead><tr><th>Ctrl[60]</th><th>Ctrl[48]</th><th>接口名格式</th><th>最终饱和行为</th></tr></thead><tbody><tr><td>0</td><td>/</td><td>不带__sat</td><td>非饱和</td></tr><tr><td>1</td><td>1</td><td>/</td><td>非饱和</td></tr><tr><td>0</td><td>/</td><td>__sat</td><td>饱和</td></tr><tr><td>1</td><td>0</td><td>/</td><td>饱和</td></tr></tbody></table><p>对如下两种情况，饱和行为只受CTRL[48]控制。</p><ul><li>窄范围数据转换为宽范围数据，且转换的目的操作数类型不是float，即half转bfloat16_t、hifloat8_t转half。</li><li>half转half、bfloat16_t转bfloat16_t。</li></ul><p>具体行为如下：</p><ul><li>当CTRL[48] = 1时，接口转换结果为非饱和模式。</li><li>当CTRL[48] = 0时，接口转换结果为饱和模式。</li></ul><p><strong>表3</strong> 窄范围数据转宽范围数据、同类型数据转换最终饱和行为</p><table><thead><tr><th>Ctrl[60]</th><th>Ctrl[48]</th><th>最终饱和行为</th></tr></thead><tbody><tr><td>/</td><td>1</td><td>非饱和</td></tr><tr><td>/</td><td>0</td><td>饱和</td></tr></tbody></table><p>对于转换的目标类型为float的情况，所有类型转换接口只支持非饱和模式。浮点数转换为整数时，转换结果均采用饱和模式。</p></article></div>',1)])])}const f=a(i,[["render",e]]);export{c as __pageData,f as default};
